head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "window",
        width: "1300px",
        height: "600px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useIFrame: true,
        scrollbars: "true",
        resizable: "true",
        menubar: true
    };
    $w.openPopup("websquare.html?w2xPath=/TEST/WS5_AT/popup_parentPopupDisabled_WPF-1575_(WSQ-2622).xml", options);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        id: "popup2",
        type: "window",
        width: "500px",
        height: "400px",
        top: "100px",
        left: "200px",
        popupName: "openPopup2",
        modal: true,
        useIFrame: true,
        scrollbars: "true",
        resizable: "true",
        menubar: true,
        parentPopupDisabled: "true"
    };
    $w.openPopup("websquare.html?w2xPath=/TEST/WS5_AT/popup_parentPopupDisabled_WPF-1575_(WSQ-2622).xml", options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    imports("uiplugin.popup");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
